package main

import (
	"fmt"
	"runtime"
	"sync"
)

func inner() {
	defer fmt.Println(2)
	runtime.Goexit()
	fmt.Println(9)
}

func main() {
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		defer fmt.Println(1)
		inner()
		fmt.Println(8)
	}()
	wg.Wait()
	fmt.Println(0)
}

package main

import (
	"fmt"
	"runtime"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		defer func() {
			if recover() == nil {
				fmt.Println(1)
			} else {
				fmt.Println(0)
			}
		}()
		runtime.Goexit()
	}()
	wg.Wait()
}

