package main

import (
	"fmt"
	"sync"
)

func boom() {
	panic(5)
}

func main() {
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		defer func() {
			fmt.Println(recover())
		}()
		boom()
		fmt.Println(9)
	}()
	wg.Wait()
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	var out [3]int
	for i := 0; i < 3; i++ {
		i := i
		wg.Add(1)
		go func() {
			defer wg.Done()
			out[i] = i * i
		}()
	}
	wg.Wait()
	fmt.Println(out[0])
	fmt.Println(out[1])
	fmt.Println(out[2])
}

