	defer fmt.Println(3)
	runtime.Goexit()
}

func main() {
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		a()
		fmt.Println(0)
	}()
	wg.Wait()
}

package main

import (
	"fmt"
	"sync"
)

func main() {
	done := false
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		done = true
	}()
	wg.Wait()
	if done {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

